def process_drug_combinations_to_dict(file_path):
    """
    پردازش فایل ترکیبات دارویی و تبدیل به دیکشنری با ساختار:
    {
        "DrugCom_ID": {
            "Drug_Name_1": {"drug": ..., "chembl_id": ..., ...},
            "Drug_Name_2": {"drug": ..., "chembl_id": ..., ...},
            "Drug_Name_3": {"drug": ..., "chembl_id": ..., ...},
            ... سایر ستون‌ها ...
        },
        ...
    }
    """

    # بارگذاری فایل
    df = pd.read_csv(file_path, sep="\t")
    print(f"\nProcessing: {file_path.name}")
    print(f"Total rows: {len(df)}")

    # مجموعه برای ذخیره داروهای یکتا
    unique_drugs = set()
    for col in ["Drug_Name_1", "Drug_Name_2", "Drug_Name_3"]:
        if col in df.columns:
            unique_drugs.update(df[col].dropna().unique())

    print(f"Unique drugs found: {len(unique_drugs)}")

    # کش کردن اطلاعات داروها
    drugs_cache = {}
    for drug_name in unique_drugs:
        print(f"  Fetching info for: {drug_name}")
        try:
            drug_info = get_drug_info(drug_name)
            if drug_info:
                drugs_cache[drug_name] = drug_info
            else:
                drugs_cache[drug_name] = {
                    "drug": drug_name,
                    "chembl_id": None,
                    "smiles": None,
                    "atc_codes": None,
                    "curated_targets": None,
                    "error": "Not found in ChEMBL",
                }
        except Exception as e:
            print(f"    ❌ Error: {e}")
            drugs_cache[drug_name] = {
                "drug": drug_name,
                "chembl_id": None,
                "smiles": None,
                "atc_codes": None,
                "curated_targets": None,
                "error": str(e),
            }

    # ساخت دیکشنری نهایی با کلید DrugCom_ID
    result = {}

    # لیست ستون‌هایی که باید علاوه بر داروها حفظ شوند (به جز ستون‌های نام دارو)
    exclude_cols = [
        "Drug_Name_1",
        "Drug_Name_2",
        "Drug_Name_3",
        "DrugID_1",
        "DrugID_2",
        "DrugID_3",
        "DrugID_4",
    ]
    other_columns = [
        col for col in df.columns if col not in exclude_cols and col != "DrugCom_ID"
    ]

    for idx, row in df.iterrows():
        drug_com_id = row["DrugCom_ID"]

        # ساختار اصلی برای این DrugCom_ID
        entry = {}

        # افزودن اطلاعات داروها
        for col in ["Drug_Name_1", "Drug_Name_2", "Drug_Name_3"]:
            if col in df.columns and pd.notna(row[col]):
                drug_name = row[col]
                entry[col] = drugs_cache.get(
                    drug_name,
                    {
                        "drug": drug_name,
                        "chembl_id": None,
                        "smiles": None,
                        "atc_codes": None,
                        "curated_targets": None,
                        "error": "Not in cache",
                    },
                )
            else:
                entry[col] = None

        # افزودن سایر ستون‌ها
        for col in other_columns:
            if col in df.columns:
                # تبدیل مقادیر NaN به None برای JSON
                value = row[col]
                if pd.isna(value):
                    entry[col] = None
                else:
                    entry[col] = value

        result[drug_com_id] = entry

    print(f"✅ Processed {len(result)} combinations")
    return result


def save_to_json(data, output_path):
    """ذخیره دیکشنری در فایل JSON"""
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False, default=str)
    print(f"✅ Saved to: {output_path}")


